d("D011","Phase","integer-frequency phase functions","For integers a,b,c and k=a+b+c, set p=a+b, alpha=3*a*b*p, beta=3*k*c*p, Phi=alpha+beta=k^3-a^3-b^3-c^3.",[],[]);
d("D012","Nthird","positive third-largest-frequency function","For nonzero integers a,b,c,d with a+b+c+d=0, let N1>=N2>=N3>=N4 be the decreasing rearrangement of |a|,|b|,|c|,|d|, resolving ties in any order. Nthird(a,b,c,d)=N3. Thus N3 is the second smallest of all four magnitudes including the dual output.",[],[]);
d("D013","R2","family of trilinear Fourier operators initially on mean-zero trigonometric polynomials","For tau>0, real base time t_n and k!=0, hat R2_(t_n,tau)(f1,f2,f3)(k)=-(tau/(18*i*k))*sum_{a+b+c=k,a+b!=0}exp(-i*t_n*Phi)*eta_tau(alpha,beta)*hat f1(a)*hat f2(b)*hat f3(c), with zero coefficient at k=0; Phase gives alpha,beta,Phi. Write R2^n_tau for t_n=n*tau. Bounded extensions, when used, are proved below.",["D002","D010","D011"],["Fourier","eta","Phase"]);
d("D014","pstar","positive real exponent","pstar=23/14.");
d("D015","B","time-dependent bilinear distribution-valued map","B_t(f,g)=S_(-t) partial_x[(S_t f)(S_t g)]. Initially use smooth inputs; the negative Sobolev extension to L^2 inputs is proved below.",["D004","D007"],["S","Dinv"]);
d("D016","J","time-dependent bilinear map","J_t(f,g)=S_(-t)P[(S_t Dinv f)(S_t Dinv g)].",["D004","D006","D007"],["S","P","Dinv"]);
d("D017","Ctri","interval-dependent trilinear integral","For I=[a,b], C_I(f,g,h)=integral_a^b S_(-t)P{P[(S_t f(t))(S_t g(t))]*(S_t Dinv h(t))}dt. Constant inputs are identified with constant time paths. At smooth inputs this is an ordinary integral, and the source estimates supply its continuous extensions.",["D004","D006","D007"],["S","P","Dinv"]);
d("D018","X","norm on time paths with weak derivative","For an interval I, ||f||_(X(I))=||f||_(L^infty(I;L^2))+||partial_t f||_(L^infty(I;H^(-pstar))). Use the continuous L^2 representative wherever supplied.",["D003","D014"],["Sob","pstar"]);
d("D019","Stage","family of bilinear integrated quadratic stages","For a base time a>=0, step tau>0, t in [a,a+tau], and constant mean-zero inputs f,g, F_a(t;f,g)=(1/2)integral_a^t B_s(f,g)ds. Abbreviate F_a(t;f)=F_a(t;f,f). Its endpoint representation and extensions are proved below.",["D015"],["B"]);
d("D020","KdV","distributional evolution equation and smooth-approximation solution convention","KdV is u_t+u_xxx=(1/2)partial_x(u^2), u(0)=u0, with real mean-zero data on Torus. An exact solution at regularity sigma>=0 means its unique real mean-zero C([0,T];H^sigma) distributional solution obtained as the limit of smooth-data solutions. This convention alone grants neither existence nor a bound; these are proved from the registered flow source. For an existing solution write its twisted path v(t)=S_(-t)u(t).",["D001","D003","D004"],["Torus","Sob","S","T"]);
