[["tau","real step"],["M","real bound"],["v","twisted exact solution"],["I","time interval"],["a","grid-start time"],["b","right endpoint"],["h","interval length",1,5,"definition","Set h=b-a."],["e","error path",1,5,"definition","Set e=v-V."],["E_I","error supremum",1,5,"definition","Set E_I=sup_I||e||_2."],["N","real threshold"],["g","midpoint path",1,5,"definition","Set g=v-e/2."],["Fint","integrated quadratic error",1,5,"definition","Set Fint(t)=integral_a^t B_s(e,g)ds."],["Lcut","low projection",3,3,"definition","Set Lcut=P_(<=N/3)."],["Hcut","high projection",3,3,"definition","Set Hcut=I-Lcut."]],
[
